export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search product names case-insensitively and return matching products.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Substring to search for in product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, limit } = args || {};

  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  let resolvedLimit;
  if (limit === undefined) {
    resolvedLimit = 10;
  } else {
    if (typeof limit !== 'number' || !Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    resolvedLimit = limit;
  }

  const needle = query.toLowerCase();
  const matches = products
    .filter((p) => typeof p.name === 'string' && p.name.toLowerCase().includes(needle))
    .slice(0, resolvedLimit);

  if (matches.length === 0) {
    return {
      content: [{ type: 'text', text: 'No matching products found.' }]
    };
  }

  const text = matches.map((p) => `${p.id}: ${p.name}`).join('\n');
  return {
    content: [{ type: 'text', text }]
  };
}

